            </tr>
            <tr>
              <td>2</td>
              <td>{Finding}</td>
              <td><span class="badge medium">Medium</span> {Why}</td>
            </tr>
          </tbody>
        </table>
      </section>

      <section>
        <h2>{Data Section}</h2>
        <p>{Context for this data.}</p>
        <!-- Table or styled data here -->
        <div class="accent-box">
          <strong>Takeaway</strong>
          {One sentence: the "so what?" of this section.}
        </div>
